  "overlays/drawer-proxy-test.html": "<div class=\"drawer-overlay\" onclick=\"closeOverlay('drawer-proxy-test')\"></div>\n<aside class=\"drawer\" id=\"drawer-proxy-test\">\n  <div class=\"drawer-header\">\n    <div>\n      <div class=\"drawer-title\" id=\"proxy-test-title\">代理测试</div>\n      <div class=\"drawer-subtitle\">模拟 Responses / Messages 请求路径。</div>\n    </div>\n    <div class=\"section-spacer\"></div>\n    <button class=\"close-btn\" type=\"button\" onclick=\"closeOverlay('drawer-proxy-test')\">x</button>\n  </div>\n  <div class=\"drawer-body\" id=\"proxy-test-body\"></div>\n  <div class=\"drawer-footer\">\n    <button class=\"btn-secondary\" type=\"button\" onclick=\"closeOverlay('drawer-proxy-test')\">关闭</button>\n    <button class=\"btn-primary\" type=\"button\" onclick=\"runProxyTest()\">Run test</button>\n  </div>\n</aside>",
